"""Signed Gaussian quadratic concentration; true PSD conditional experiment, fixed alpha=.05."""
import numpy as np
from study_noise_paired_uncertainty import run as experiment,ALPHA,quadratic_variance
from study_noise_spectral_identifiability import run as prepare


X=float(np.log(8/ALPHA))


def deviations(eigenvalues,x=X):
    values=np.asarray(eigenvalues,dtype=float)
    if not np.isfinite(values).all() or values.size==0 or not np.isfinite(x) or x<=0:raise ValueError('Finite eigenvalues and positive tail exponent required')
    squared=float(np.sum(values*values));base=2*np.sqrt(squared*x)
    return dict(lower_deviation=float(base+2*max(0.,float(-values.min()))*x),
        upper_deviation=float(base+2*max(0.,float(values.max()))*x),
        sum_squared_eigenvalues=squared,minimum_eigenvalue=float(values.min()),maximum_eigenvalue=float(values.max()),tail_exponent=x)


def model_bounds(spectrum):
    n=spectrum.shape[0]*spectrum.shape[1]
    hermitian=(spectrum+spectrum.swapaxes(-1,-2).conj())/2
    values,vectors=np.linalg.eigh(hermitian)
    if values.min() < -1e-8:raise ValueError('PSD required')
    root=(vectors*np.sqrt(np.maximum(values,0))[...,None,:])@vectors.swapaxes(-1,-2).conj()
    fy=np.fft.fftfreq(spectrum.shape[0])[:,None];fx=np.fft.fftfreq(spectrum.shape[1])[None,:]
    hh=4*np.sin(np.pi*fy)**2*np.sin(np.pi*fx)**2
    hh_bounds=[deviations(hh*spectrum[:,:,a,a].real/n) for a in range(3)]
    def covariance_bounds(symbol):
        product=root@symbol@root
        product=(product+product.swapaxes(-1,-2).conj())/2
        eigen=np.linalg.eigvalsh(product)/n
        result=deviations(eigen)
        exact=quadratic_variance(symbol,spectrum)
        if not np.isclose(2*result['sum_squared_eigenvalues'],exact,rtol=1e-9,atol=1e-25):raise ValueError('Eigen/trace variance mismatch')
        return result
    return dict(hh_upper_deviation=np.array([r['upper_deviation'] for r in hh_bounds]),
        hh_lower_deviation=np.array([r['lower_deviation'] for r in hh_bounds]),covariance_bounds=covariance_bounds)


def run(*args):return experiment(*args,bound_factory=model_bounds)


if __name__=='__main__':prepare(study_callback=run)
